CREATE OR REPLACE FUNCTION public.get_instant_kpis(p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$ DECLARE result jsonb; user_filter uuid := p_user_id; BEGIN SELECT jsonb_build_object( 'timestamp', now(), 'empresas', jsonb_build_object( 'total', (SELECT COUNT(*) FROM companies WHERE deleted_at IS NULL AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)), 'ativas', (SELECT COUNT(*) FROM companies WHERE status = 'ativo' AND deleted_at IS NULL AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)), 'novas_hoje', (SELECT COUNT(*) FROM companies WHERE created_at::date = CURRENT_DATE AND deleted_at IS NULL AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)), 'novas_semana', (SELECT COUNT(*) FROM companies WHERE created_at >= date_trunc('week', now()) AND deleted_at IS NULL AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)) ), 'clientes', jsonb_build_object( 'total', (SELECT COUNT(*) FROM customers WHERE deleted_at IS NULL), 'ativados', (SELECT COUNT(*) FROM customers WHERE cliente_ativado = true AND deleted_at IS NULL), 'compradores', (SELECT COUNT(*) FROM customers WHERE ja_comprou = true AND deleted_at IS NULL), 'valor_total', (SELECT COALESCE(SUM(valor_total_compras), 0) FROM customers WHERE deleted_at IS NULL) ), 'interacoes', jsonb_build_object( 'hoje', (SELECT COUNT(*) FROM interactions WHERE created_at::date = CURRENT_DATE AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)), 'semana', (SELECT COUNT(*) FROM interactions WHERE created_at >= date_trunc('week', now()) AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)), 'mes', (SELECT COUNT(*) FROM interactions WHERE created_at >= date_trunc('month', now()) AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)) ), 'alertas', jsonb_build_object( 'pendentes', (SELECT COUNT(*) FROM alerts WHERE status = 'pending' AND dismissed = false AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)), 'alta_prioridade', (SELECT COUNT(*) FROM alerts WHERE status = 'pending' AND dismissed = false AND priority = 'high' AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)) ), 'followups', jsonb_build_object( 'pendentes', (SELECT COUNT(*) FROM interactions WHERE requer_followup = true AND followup_concluido = false AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)), 'atrasados', (SELECT COUNT(*) FROM interactions WHERE requer_followup = true AND followup_concluido = false AND data_followup < now() AND (user_filter IS NULL OR user_id IS NULL OR user_id = user_filter)) ) ) INTO result; RETURN result; END; $function$
